vector<int> adjacency[MAXNODES];

long long total_cost = 0;
long long dist_array[MAXNODES];
int parent_node[MAXNODES], parent_edge[MAXNODES], in_queue_flag[MAXNODES];

const long long INF_VAL = 1e18;
int s_node = MAXNODES - 2;
int t_node = MAXNODES - 1;

int get_capacity(int idx) {
    return all_edges[idx].c - all_edges[idx].f;
}

void find_min_cost_flow() {
    for (int i = 0; i < MAXNODES; i++) {
        dist_array[i] = INF_VAL;
        parent_node[i] = -1;
        parent_edge[i] = -1;
        in_queue_flag[i] = 0;
    }
    dist_array[s_node] = 0;
    queue<int> q;
    q.push(s_node);
    in_queue_flag[s_node] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue_flag[u] = 0;
        for (auto e_idx : adjacency[u]) {
