import java.util.*;

class Main {
    static class Edge {
        int y, c, f, cost;
        Edge() {}
        Edge(int y, int c, int f, int cost) {
            this.y = y;
            this.c = c;
            this.f = f;
            this.cost = cost;
        }
    }

    static List<Edge> allEdges = new ArrayList<>();
    static final int MAXNODES = 14043;
    static List<Integer>[] adjacency = new ArrayList[MAXNODES];

    static long totalCost = 0;
    static long[] distArray = new long[MAXNODES];
    static int[] parentNode = new int[MAXNODES];
    static int[] parentEdge = new int[MAXNODES];
    static int[] inQueueFlag = new int[MAXNODES];

    static final long INF_VAL = (long)1e18;
    static int sNode = MAXNODES - 2;
    static int tNode = MAXNODES - 1;

    static {
        for (int i = 0; i < MAXNODES; i++) {
            adjacency[i] = new ArrayList<>();
        }
    }

    static int getCapacity(int idx) {
        return allEdges.get(idx).c - allEdges.get(idx).f;
    }

    static void findMinCostFlow() {
        Arrays.fill(distArray, INF_VAL);
        Arrays.fill(parentNode, -1);
        Arrays.fill(parentEdge, -1);
        Arrays.fill(inQueueFlag, 0);
        distArray[sNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sNode);
        inQueueFlag[sNode] = 1;

        while (!q.isEmpty()) {
            int u = q.poll();
            inQueueFlag[u] = 0;
            for (int eIdx : adjacency[u]) {
                if (getCapacity(eIdx) == 0) continue;
                int cst = allEdges.get(eIdx).cost;
                int v = allEdges.get(eIdx).y;
                if (distArray[v] > distArray[u] + cst) {
                    distArray[v] = distArray[u] + cst;
                    parentNode[v] = u;
                    parentEdge[v] = eIdx;
                    if (inQueueFlag[v] == 0) {
                        inQueueFlag[v] = 1;
                        q.offer(v);
                    }
                }
            }
        }

        int current = tNode;
        while (current != sNode) {
            allEdges.get(parentEdge[current]).f++;
            allEdges.get(parentEdge[current] ^ 1).f--;
            current = parentNode[current];
        }
        totalCost += distArray[tNode];
    }

    static void connect(int from, int to, int cap, int cst) {
        adjacency[from].add(allEdges.size());
        allEdges.add(new Edge(to, cap, 0, cst));
        adjacency[to].add(allEdges.size());
        allEdges.add(new Edge(from, 0, 0, -cst));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            connect(sNode, x, 1, 0);
        }

        int tt = 101;
        for (int i = 0; i < tt; i++) {
            connect(1 + i * n, tNode, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            for (int j = 0; j < tt - 1; j++) {
                connect(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
                connect(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < tt - 1; j++) {
                connect(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            findMinCostFlow();
        }

        System.out.println(totalCost);
        sc.close();
    }
}
